#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum OperationPrecondition {
    NoPrecondition,
    AccountExistsCheck {
        login: NonEmptyStr,
    },
}
impl OperationPrecondition {
    pub fn login(&self) -> NonEmptyStr {
        match self {
            OperationPrecondition::NoPrecondition => panic!("no login on unit variant"),
            OperationPrecondition::AccountExistsCheck { login: __val, .. } => __val.clone(),
        }
    }
}

